INSERT INTO cache VALUES('settings_','a:4:{s:7:"general";a:7:{s:13:"fa_brand_name";s:40:"گروه رسانه ای صبح ساحل";s:14:"fa_brand_about";s:30:"روزنامه صبح ساحل";s:20:"fa_brand_description";N;s:13:"en_brand_name";s:10:"SobheSahel";s:14:"en_brand_about";s:20:"SobheSahel NewsPaper";s:20:"en_brand_description";N;s:7:"fa_logo";s:30:"01JMJ2W6XEEQZE3HCFNX3PRFEC.svg";}s:7:"contact";a:8:{s:11:"fa_whatsapp";s:20:"https://whatsapp.com";s:10:"fa_address";s:92:"هرمزگان، خیابان آفتاب، فرعی اول، کوچه گل هاب بنفشه";s:8:"fa_phone";s:10:"9123208185";s:8:"fa_email";s:20:"admin@sobhesahel.com";s:11:"en_whatsapp";s:20:"https://whatsapp.com";s:10:"en_address";s:46:"Golhab alley , Aftab Street , Hormozgan , Iran";s:8:"en_phone";s:10:"9123208185";s:8:"en_email";s:20:"admin@sobhesahel.com";}s:6:"social";a:7:{s:1:"x";N;s:8:"telegram";N;s:9:"instagram";N;s:8:"linkedin";N;s:4:"bale";N;s:4:"eita";N;s:7:"youtube";N;}s:5:"about";a:2:{s:2:"fa";s:2992:"<h2 dir="rtl">تیم صبح ساحل</h2><p dir="rtl">لورم ایپسوم یا طرح‌نما (به انگلیسی: Lorem ipsum) متنی آزمایشی و بی‌معنی در صنعت چاپ، صفحه‌آرایی و طراحی گرافیک گفته می‌شود. طراح گرافیک از این متن به عنوان عنصری از ترکیب بندی برای پر کردن صفحه و ارایه اولیه شکل ظاهری و کلی طرح سفارش گرفته شده استفاده می نماید، تا از نظر گرافیکی نشانگر چگونگی نوع و اندازه فونت و ظاهر متن باشد. معمولا طراحان گرافیک برای صفحه‌آرایی، نخست از متن‌های آزمایشی و بی‌معنی استفاده می‌کنند تا صرفا به مشتری یا صاحب کار خود نشان دهند که صفحه طراحی یا صفحه بندی شده بعد از اینکه متن در آن قرار گیرد چگونه به نظر می‌رسد و قلم‌ها و اندازه‌بندی‌ها چگونه در نظر گرفته شده‌است. از آنجایی که طراحان عموما نویسنده متن نیستند و وظیفه رعایت حق تکثیر متون را ندارند و در همان حال کار آنها به نوعی وابسته به متن می‌باشد آنها با استفاده از محتویات ساختگی، صفحه گرافیکی خود را صفحه‌آرایی می‌کنند تا مرحله طراحی و صفحه‌بندی را به پایان برند.</p><h2 dir="rtl">&nbsp;صبح ساحل</h2><p dir="rtl">صاحب کار خود نشان دهند که صفحه طراحی یا صفحه بندی شده بعد از اینکه متن در آن قرار گیرد چگونه به نظر می‌رسد و قلم‌ها و اندازه‌بندی‌ها چگونه در نظر گرفته شده‌است. از آنجایی که طراحان عموما نویسنده متن نیستند و وظیفه رعایت حق تکثیر متون را ندارند و در همان حال کار آنها به نوعی وابسته به متن می‌باشد</p><h2 dir="rtl">روزنامه</h2><p dir="rtl">صاحب کار خود نشان دهند که صفحه طراحی یا صفحه بندی شده بعد از اینکه متن در آن قرار گیرد چگونه به نظر می‌رسد و قلم‌ها و اندازه‌بندی‌ها چگونه در نظر گرفته شده‌است. از آنجایی که طراحان عموما نویسنده متن نیستند و وظیفه رعایت حق تکثیر متون را ندارند و در همان حال کار آنها به نوعی وابسته به متن می‌باشد</p><h2 dir="rtl">همکاری</h2><p dir="rtl">صاحب کار خود نشان دهند که صفحه طراحی یا صفحه بندی شده بعد از اینکه متن در آن قرار گیرد</p><p><br></p>";s:2:"en";s:1225:"<h2>Lorem ipsum dolor</h2><p>Lorem ipsum dolor sit amet consectetur adipisicing elit. Numquam nostrum officiis ullam itaque saepe est natus dolor ea accusantium alias fuga sunt commodi et doloremque provident dignissimos, a recusandae veniam? Lorem ipsum dolor sit amet consectetur adipisicing elit. Vero iure atque, fugiat explicabo tempore eum nemo fuga veniam dolor rem ipsum, qui ducimus, animi esse. Nulla necessitatibus quae officia quaerat.</p><h2>Lorem ipsum dolor</h2><p>Lorem ipsum dolor sit amet consectetur adipisicing elit. Vero iure atque, fugiat explicabo tempore eum nemo fuga veniam dolor rem ipsum, qui ducimus, animi esse. Nulla necessitatibus quae officia quaerat.</p><h2>Lorem ipsum</h2><p>Lorem ipsum dolor sit amet consectetur, adipisicing elit. Repudiandae reprehenderit error saepe harum beatae tempore voluptatem numquam ipsa quam veniam aliquid velit atque deleniti repellendus, neque eius exercitationem culpa qui?</p><h2>Lorem ipsum</h2><p>Lorem ipsum dolor sit amet consectetur adipisicing elit. Tempora quis accusantium minima eius ipsam similique soluta neque asperiores perspiciatis? Animi, velit at. Asperiores dignissimos consequuntur nulla reiciendis sapiente delectus fuga.</p><p><br></p>";}}',2056034549);
