INSERT INTO settings VALUES(21,'about.fa','"<h2 dir=\"rtl\">\u062a\u06cc\u0645 \u0635\u0628\u062d \u0633\u0627\u062d\u0644<\/h2><p dir=\"rtl\">\u0644\u0648\u0631\u0645 \u0627\u06cc\u067e\u0633\u0648\u0645 \u06cc\u0627 \u0637\u0631\u062d\u200c\u0646\u0645\u0627 (\u0628\u0647 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc: Lorem ipsum) \u0645\u062a\u0646\u06cc \u0622\u0632\u0645\u0627\u06cc\u0634\u06cc \u0648 \u0628\u06cc\u200c\u0645\u0639\u0646\u06cc \u062f\u0631 \u0635\u0646\u0639\u062a \u0686\u0627\u067e\u060c \u0635\u0641\u062d\u0647\u200c\u0622\u0631\u0627\u06cc\u06cc \u0648 \u0637\u0631\u0627\u062d\u06cc \u06af\u0631\u0627\u0641\u06cc\u06a9 \u06af\u0641\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0637\u0631\u0627\u062d \u06af\u0631\u0627\u0641\u06cc\u06a9 \u0627\u0632 \u0627\u06cc\u0646 \u0645\u062a\u0646 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u0639\u0646\u0635\u0631\u06cc \u0627\u0632 \u062a\u0631\u06a9\u06cc\u0628 \u0628\u0646\u062f\u06cc \u0628\u0631\u0627\u06cc \u067e\u0631 \u06a9\u0631\u062f\u0646 \u0635\u0641\u062d\u0647 \u0648 \u0627\u0631\u0627\u06cc\u0647 \u0627\u0648\u0644\u06cc\u0647 \u0634\u06a9\u0644 \u0638\u0627\u0647\u0631\u06cc \u0648 \u06a9\u0644\u06cc \u0637\u0631\u062d \u0633\u0641\u0627\u0631\u0634 \u06af\u0631\u0641\u062a\u0647 \u0634\u062f\u0647 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0645\u06cc \u0646\u0645\u0627\u06cc\u062f\u060c \u062a\u0627 \u0627\u0632 \u0646\u0638\u0631 \u06af\u0631\u0627\u0641\u06cc\u06a9\u06cc \u0646\u0634\u0627\u0646\u06af\u0631 \u0686\u06af\u0648\u0646\u06af\u06cc \u0646\u0648\u0639 \u0648 \u0627\u0646\u062f\u0627\u0632\u0647 \u0641\u0648\u0646\u062a \u0648 \u0638\u0627\u0647\u0631 \u0645\u062a\u0646 \u0628\u0627\u0634\u062f. \u0645\u0639\u0645\u0648\u0644\u0627 \u0637\u0631\u0627\u062d\u0627\u0646 \u06af\u0631\u0627\u0641\u06cc\u06a9 \u0628\u0631\u0627\u06cc \u0635\u0641\u062d\u0647\u200c\u0622\u0631\u0627\u06cc\u06cc\u060c \u0646\u062e\u0633\u062a \u0627\u0632 \u0645\u062a\u0646\u200c\u0647\u0627\u06cc \u0622\u0632\u0645\u0627\u06cc\u0634\u06cc \u0648 \u0628\u06cc\u200c\u0645\u0639\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0645\u06cc\u200c\u06a9\u0646\u0646\u062f \u062a\u0627 \u0635\u0631\u0641\u0627 \u0628\u0647 \u0645\u0634\u062a\u0631\u06cc \u06cc\u0627 \u0635\u0627\u062d\u0628 \u06a9\u0627\u0631 \u062e\u0648\u062f \u0646\u0634\u0627\u0646 \u062f\u0647\u0646\u062f \u06a9\u0647 \u0635\u0641\u062d\u0647 \u0637\u0631\u0627\u062d\u06cc \u06cc\u0627 \u0635\u0641\u062d\u0647 \u0628\u0646\u062f\u06cc \u0634\u062f\u0647 \u0628\u0639\u062f \u0627\u0632 \u0627\u06cc\u0646\u06a9\u0647 \u0645\u062a\u0646 \u062f\u0631 \u0622\u0646 \u0642\u0631\u0627\u0631 \u06af\u06cc\u0631\u062f \u0686\u06af\u0648\u0646\u0647 \u0628\u0647 \u0646\u0638\u0631 \u0645\u06cc\u200c\u0631\u0633\u062f \u0648 \u0642\u0644\u0645\u200c\u0647\u0627 \u0648 \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u0628\u0646\u062f\u06cc\u200c\u0647\u0627 \u0686\u06af\u0648\u0646\u0647 \u062f\u0631 \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0647 \u0634\u062f\u0647\u200c\u0627\u0633\u062a. \u0627\u0632 \u0622\u0646\u062c\u0627\u06cc\u06cc \u06a9\u0647 \u0637\u0631\u0627\u062d\u0627\u0646 \u0639\u0645\u0648\u0645\u0627 \u0646\u0648\u06cc\u0633\u0646\u062f\u0647 \u0645\u062a\u0646 \u0646\u06cc\u0633\u062a\u0646\u062f \u0648 \u0648\u0638\u06cc\u0641\u0647 \u0631\u0639\u0627\u06cc\u062a \u062d\u0642 \u062a\u06a9\u062b\u06cc\u0631 \u0645\u062a\u0648\u0646 \u0631\u0627 \u0646\u062f\u0627\u0631\u0646\u062f \u0648 \u062f\u0631 \u0647\u0645\u0627\u0646 \u062d\u0627\u0644 \u06a9\u0627\u0631 \u0622\u0646\u0647\u0627 \u0628\u0647 \u0646\u0648\u0639\u06cc \u0648\u0627\u0628\u0633\u062a\u0647 \u0628\u0647 \u0645\u062a\u0646 \u0645\u06cc\u200c\u0628\u0627\u0634\u062f \u0622\u0646\u0647\u0627 \u0628\u0627 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0632 \u0645\u062d\u062a\u0648\u06cc\u0627\u062a \u0633\u0627\u062e\u062a\u06af\u06cc\u060c \u0635\u0641\u062d\u0647 \u06af\u0631\u0627\u0641\u06cc\u06a9\u06cc \u062e\u0648\u062f \u0631\u0627 \u0635\u0641\u062d\u0647\u200c\u0622\u0631\u0627\u06cc\u06cc \u0645\u06cc\u200c\u06a9\u0646\u0646\u062f \u062a\u0627 \u0645\u0631\u062d\u0644\u0647 \u0637\u0631\u0627\u062d\u06cc \u0648 \u0635\u0641\u062d\u0647\u200c\u0628\u0646\u062f\u06cc \u0631\u0627 \u0628\u0647 \u067e\u0627\u06cc\u0627\u0646 \u0628\u0631\u0646\u062f.<\/p><h2 dir=\"rtl\">&nbsp;\u0635\u0628\u062d \u0633\u0627\u062d\u0644<\/h2><p dir=\"rtl\">\u0635\u0627\u062d\u0628 \u06a9\u0627\u0631 \u062e\u0648\u062f \u0646\u0634\u0627\u0646 \u062f\u0647\u0646\u062f \u06a9\u0647 \u0635\u0641\u062d\u0647 \u0637\u0631\u0627\u062d\u06cc \u06cc\u0627 \u0635\u0641\u062d\u0647 \u0628\u0646\u062f\u06cc \u0634\u062f\u0647 \u0628\u0639\u062f \u0627\u0632 \u0627\u06cc\u0646\u06a9\u0647 \u0645\u062a\u0646 \u062f\u0631 \u0622\u0646 \u0642\u0631\u0627\u0631 \u06af\u06cc\u0631\u062f \u0686\u06af\u0648\u0646\u0647 \u0628\u0647 \u0646\u0638\u0631 \u0645\u06cc\u200c\u0631\u0633\u062f \u0648 \u0642\u0644\u0645\u200c\u0647\u0627 \u0648 \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u0628\u0646\u062f\u06cc\u200c\u0647\u0627 \u0686\u06af\u0648\u0646\u0647 \u062f\u0631 \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0647 \u0634\u062f\u0647\u200c\u0627\u0633\u062a. \u0627\u0632 \u0622\u0646\u062c\u0627\u06cc\u06cc \u06a9\u0647 \u0637\u0631\u0627\u062d\u0627\u0646 \u0639\u0645\u0648\u0645\u0627 \u0646\u0648\u06cc\u0633\u0646\u062f\u0647 \u0645\u062a\u0646 \u0646\u06cc\u0633\u062a\u0646\u062f \u0648 \u0648\u0638\u06cc\u0641\u0647 \u0631\u0639\u0627\u06cc\u062a \u062d\u0642 \u062a\u06a9\u062b\u06cc\u0631 \u0645\u062a\u0648\u0646 \u0631\u0627 \u0646\u062f\u0627\u0631\u0646\u062f \u0648 \u062f\u0631 \u0647\u0645\u0627\u0646 \u062d\u0627\u0644 \u06a9\u0627\u0631 \u0622\u0646\u0647\u0627 \u0628\u0647 \u0646\u0648\u0639\u06cc \u0648\u0627\u0628\u0633\u062a\u0647 \u0628\u0647 \u0645\u062a\u0646 \u0645\u06cc\u200c\u0628\u0627\u0634\u062f<\/p><h2 dir=\"rtl\">\u0631\u0648\u0632\u0646\u0627\u0645\u0647<\/h2><p dir=\"rtl\">\u0635\u0627\u062d\u0628 \u06a9\u0627\u0631 \u062e\u0648\u062f \u0646\u0634\u0627\u0646 \u062f\u0647\u0646\u062f \u06a9\u0647 \u0635\u0641\u062d\u0647 \u0637\u0631\u0627\u062d\u06cc \u06cc\u0627 \u0635\u0641\u062d\u0647 \u0628\u0646\u062f\u06cc \u0634\u062f\u0647 \u0628\u0639\u062f \u0627\u0632 \u0627\u06cc\u0646\u06a9\u0647 \u0645\u062a\u0646 \u062f\u0631 \u0622\u0646 \u0642\u0631\u0627\u0631 \u06af\u06cc\u0631\u062f \u0686\u06af\u0648\u0646\u0647 \u0628\u0647 \u0646\u0638\u0631 \u0645\u06cc\u200c\u0631\u0633\u062f \u0648 \u0642\u0644\u0645\u200c\u0647\u0627 \u0648 \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u0628\u0646\u062f\u06cc\u200c\u0647\u0627 \u0686\u06af\u0648\u0646\u0647 \u062f\u0631 \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0647 \u0634\u062f\u0647\u200c\u0627\u0633\u062a. \u0627\u0632 \u0622\u0646\u062c\u0627\u06cc\u06cc \u06a9\u0647 \u0637\u0631\u0627\u062d\u0627\u0646 \u0639\u0645\u0648\u0645\u0627 \u0646\u0648\u06cc\u0633\u0646\u062f\u0647 \u0645\u062a\u0646 \u0646\u06cc\u0633\u062a\u0646\u062f \u0648 \u0648\u0638\u06cc\u0641\u0647 \u0631\u0639\u0627\u06cc\u062a \u062d\u0642 \u062a\u06a9\u062b\u06cc\u0631 \u0645\u062a\u0648\u0646 \u0631\u0627 \u0646\u062f\u0627\u0631\u0646\u062f \u0648 \u062f\u0631 \u0647\u0645\u0627\u0646 \u062d\u0627\u0644 \u06a9\u0627\u0631 \u0622\u0646\u0647\u0627 \u0628\u0647 \u0646\u0648\u0639\u06cc \u0648\u0627\u0628\u0633\u062a\u0647 \u0628\u0647 \u0645\u062a\u0646 \u0645\u06cc\u200c\u0628\u0627\u0634\u062f<\/p><h2 dir=\"rtl\">\u0647\u0645\u06a9\u0627\u0631\u06cc<\/h2><p dir=\"rtl\">\u0635\u0627\u062d\u0628 \u06a9\u0627\u0631 \u062e\u0648\u062f \u0646\u0634\u0627\u0646 \u062f\u0647\u0646\u062f \u06a9\u0647 \u0635\u0641\u062d\u0647 \u0637\u0631\u0627\u062d\u06cc \u06cc\u0627 \u0635\u0641\u062d\u0647 \u0628\u0646\u062f\u06cc \u0634\u062f\u0647 \u0628\u0639\u062f \u0627\u0632 \u0627\u06cc\u0646\u06a9\u0647 \u0645\u062a\u0646 \u062f\u0631 \u0622\u0646 \u0642\u0631\u0627\u0631 \u06af\u06cc\u0631\u062f<\/p><p><br><\/p>"','2025-02-15 17:50:17','2025-02-15 17:50:17');
