PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "custom_fields" text, "avatar_url" varchar, "mobile" varchar);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "parent_id" integer, "title" varchar not null, "en_title" varchar, "slug" varchar not null, "en_slug" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "category_news" ("id" integer primary key autoincrement not null, "news_id" integer not null, "category_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("news_id") references "news"("id") on delete cascade, foreign key("category_id") references "categories"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "tags" ("id" integer primary key autoincrement not null, "name" text not null, "slug" text not null, "type" varchar, "order_column" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "taggables" ("tag_id" integer not null, "taggable_type" varchar not null, "taggable_id" integer not null, foreign key("tag_id") references "tags"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "news_tag" ("id" integer primary key autoincrement not null, "news_id" integer not null, "tag_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("news_id") references "news"("id") on delete cascade, foreign key("tag_id") references "tags"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "authors" ("id" integer primary key autoincrement not null, "name" varchar not null, "nik_name" varchar, "bio" text, "avatar" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "permissions" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "model_has_permissions" ("permission_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, primary key ("permission_id", "model_id", "model_type"));
CREATE TABLE IF NOT EXISTS "model_has_roles" ("role_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("role_id", "model_id", "model_type"));
CREATE TABLE IF NOT EXISTS "role_has_permissions" ("permission_id" integer not null, "role_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("permission_id", "role_id"));
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "contacts" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "text" text not null, "lang_id" integer not null default '1', "unread" tinyint(1) not null default '1', "ip_address" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "news" ("id" integer primary key autoincrement not null, "title" varchar not null, "sub_title" varchar, "slug" varchar not null, "user_id" integer not null, "author_id" integer, "image_large" varchar, "image_medium" varchar, "image_small" varchar, "meta_desc" text, "seo_title" varchar, "body" text not null, "short_description" text, "lang_id" integer not null, "visits" integer not null default '0', "is_published" tinyint(1) not null default '0', "publish_at" datetime, "status" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "galleries" ("id" integer primary key autoincrement not null, "title" varchar not null, "sub_title" varchar, "slug" varchar not null, "user_id" integer not null, "author_id" integer, "image_large" varchar, "image_medium" varchar, "image_small" varchar, "meta_desc" text, "seo_title" varchar, "body" text not null, "short_description" text, "lang_id" integer not null, "visits" integer not null default '0', "attachments" text, "is_published" tinyint(1) not null default '0', "publish_at" datetime, "status" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "podcasts" ("id" integer primary key autoincrement not null, "title" varchar not null, "sub_title" varchar, "slug" varchar not null, "user_id" integer not null, "author_id" integer, "image_large" varchar, "image_medium" varchar, "image_small" varchar, "meta_desc" text, "seo_title" varchar, "body" text not null, "short_description" text, "lang_id" integer not null, "visits" integer not null default '0', "attachments" text, "is_published" tinyint(1) not null default '0', "publish_at" datetime, "status" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "notes" ("id" integer primary key autoincrement not null, "title" varchar not null, "sub_title" varchar, "slug" varchar not null, "user_id" integer not null, "author_id" integer, "image_large" varchar, "image_medium" varchar, "image_small" varchar, "meta_desc" text, "seo_title" varchar, "body" text not null, "short_description" text, "lang_id" integer not null, "visits" integer not null default '0', "is_published" tinyint(1) not null default '0', "publish_at" datetime, "status" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "videos" ("id" integer primary key autoincrement not null, "title" varchar not null, "sub_title" varchar, "slug" varchar not null, "user_id" integer not null, "author_id" integer, "image_large" varchar, "image_medium" varchar, "image_small" varchar, "meta_desc" text, "seo_title" varchar, "body" text not null, "short_description" text, "lang_id" integer not null, "visits" integer not null default '0', "attachments" text, "embed" varchar, "is_published" tinyint(1) not null default '0', "publish_at" datetime, "status" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "polls" ("id" integer primary key autoincrement not null, "user_id" integer not null, "question" text not null, "lang_id" integer not null default '1', "is_active" tinyint(1) not null default '1', "login_required" tinyint(1) not null default '0', "starts_at" datetime, "ends_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "poll_votes" ("id" integer primary key autoincrement not null, "poll_id" integer not null, "poll_option_id" integer not null, "user_id" integer, "user_ip" varchar, "user_agent" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "poll_options" ("id" integer primary key autoincrement not null, "poll_id" integer not null, "option_text" varchar not null, "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "advertises" ("id" integer primary key autoincrement not null, "name" varchar not null, "image" varchar, "text" text, "url" varchar not null, "view" integer not null default '0', "click" integer not null default '0', "lang_id" integer not null default '1', "is_active" tinyint(1) not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "archive_categories" ("id" integer primary key autoincrement not null, "title" varchar not null, "en_title" varchar, "slug" varchar not null, "en_slug" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "archives" ("id" integer primary key autoincrement not null, "title" varchar not null, "user_id" integer not null, "image_large" varchar, "image_medium" varchar, "image_small" varchar, "meta_desc" text, "seo_title" varchar, "body" text, "short_description" text, "lang_id" integer not null default '1', "visits" integer not null default '0', "downloads" integer not null default '0', "archive_file" varchar not null, "attachments" text, "is_published" tinyint(1) not null default '0', "publish_at" datetime, "archive_number" integer not null, "archive_date" date, "category_id" integer not null, "status" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "comments" ("id" integer primary key autoincrement not null, "news_id" integer, "note_id" integer, "user_id" integer, "reply_to" integer, "name" varchar, "email" varchar, "comment" text not null, "status" varchar not null default 'pending', "lang_id" integer not null, "created_at" datetime, "updated_at" datetime);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "taggables_taggable_type_taggable_id_index" on "taggables" ("taggable_type", "taggable_id");
CREATE UNIQUE INDEX "taggables_tag_id_taggable_id_taggable_type_unique" on "taggables" ("tag_id", "taggable_id", "taggable_type");
CREATE UNIQUE INDEX "permissions_name_guard_name_unique" on "permissions" ("name", "guard_name");
CREATE UNIQUE INDEX "roles_name_guard_name_unique" on "roles" ("name", "guard_name");
CREATE INDEX "model_has_permissions_model_id_model_type_index" on "model_has_permissions" ("model_id", "model_type");
CREATE INDEX "model_has_roles_model_id_model_type_index" on "model_has_roles" ("model_id", "model_type");
CREATE UNIQUE INDEX "users_mobile_unique" on "users" ("mobile");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
CREATE INDEX "news_lang_id_index" on "news" ("lang_id");
CREATE INDEX "galleries_lang_id_index" on "galleries" ("lang_id");
CREATE INDEX "podcasts_lang_id_index" on "podcasts" ("lang_id");
CREATE INDEX "notes_lang_id_index" on "notes" ("lang_id");
CREATE INDEX "videos_lang_id_index" on "videos" ("lang_id");
CREATE INDEX "archives_lang_id_index" on "archives" ("lang_id");
COMMIT;
